// Scripted replies used when no AI provider is configured. These are NOT generated by an AI model
// and the app labels them as demo replies. They only reuse the user's real roadmap data.

const firstOpenTask = (roadmap) => {
  for (const m of roadmap?.milestones || []) {
    const task = (m.tasks || []).find((t) => !t.done);
    if (task) return { milestone: m.title, task: task.title };
  }
  return null;
};

const openTasks = (roadmap, count) => {
  const out = [];
  for (const m of roadmap?.milestones || []) {
    for (const t of m.tasks || []) {
      if (!t.done && out.length < count) out.push(t.title);
    }
  }
  return out;
};

export function demoReply({ message, dream, roadmap }) {
  const text = String(message || '').toLowerCase();
  const goal = dream?.career || 'your dream';

  if (!dream) {
    return 'Welcome! I am Nova. Create your dream first (Create Your Future), and I can point you to concrete next steps from your roadmap. (Demo reply: no AI model is connected.)';
  }

  if (/(motivat|stuck|tired|overwhelm|give up|procrastinat|lazy|hard)/.test(text)) {
    const next = firstOpenTask(roadmap);
    return `Big goals feel heavy when you look at all of it at once. Shrink it: pick the smallest thing you can finish in 10 minutes.${
      next ? ` For example: "${next.task}".` : ''
    } Small finished steps build momentum. (Demo reply: no AI model is connected.)`;
  }

  if (/(week|plan|schedule|this month|today)/.test(text)) {
    const tasks = openTasks(roadmap, 3);
    return tasks.length
      ? `A simple plan for this week toward ${goal}:\n- ${tasks.join('\n- ')}\nTick them off on your roadmap as you go. (Demo reply: no AI model is connected.)`
      : `You have no open roadmap tasks right now. Nice work! Consider creating a new dream or goal to keep growing. (Demo reply: no AI model is connected.)`;
  }

  if (/(skill|learn|study|course|resource|book)/.test(text)) {
    const skills = dream.skills?.length ? dream.skills.join(', ') : 'the core skills for your field';
    return `For ${goal}, start with ${skills}. Pick one beginner course, schedule three short study sessions this week, and write down one thing you learned after each. (Demo reply: no AI model is connected.)`;
  }

  const next = firstOpenTask(roadmap);
  if (/(next|start|begin|first|what should|what now|help)/.test(text) && next) {
    return `Your next step on "${next.milestone}" is: ${next.task}. Want to break it down further? (Demo reply: no AI model is connected.)`;
  }

  return `I'm in demo mode, so I can only give simple guidance based on your roadmap${
    next ? ` (your next open task is "${next.task}")` : ''
  }. Try asking: "What should I do next?", "Plan my week", or "I feel stuck". Connect an AI provider on the server for real conversations.`;
}
